import React, { useState } from 'react';

function AquariumForm({ onAquariumCreate }) {
    const [name, setName] = useState('');
    const [photoUrl, setPhotoUrl] = useState('');
    const [volume, setVolume] = useState('');
    const [type, setType] = useState('Planted'); // Default type
    // For simplicity, targetParameters and initialSetupNotes are strings for now
    const [targetParameters, setTargetParameters] = useState(''); 
    const [initialSetupNotes, setInitialSetupNotes] = useState('');

    const handleSubmit = (e) => {
        e.preventDefault();
        if (!name || !volume) {
            alert('Name and Volume are required!');
            return;
        }
        const newAquarium = {
            // In a real app, ID would be generated by the backend
            id: Date.now().toString(), 
            name,
            photoUrl,
            volume: parseFloat(volume),
            type,
            targetParameters, // Will be a string like "pH: 7, Temp: 25C"
            initialSetupNotes
        };
        onAquariumCreate(newAquarium);
        // Reset form
        setName('');
        setPhotoUrl('');
        setVolume('');
        setType('Planted');
        setTargetParameters('');
        setInitialSetupNotes('');
    };

    return (
        <form onSubmit={handleSubmit} style={{ marginBottom: '20px', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
            <h3>Create New Aquarium</h3>
            <div>
                <label>Name: </label>
                <input type="text" value={name} onChange={(e) => setName(e.target.value)} required />
            </div>
            <div>
                <label>Photo URL: </label>
                <input type="text" value={photoUrl} onChange={(e) => setPhotoUrl(e.target.value)} />
            </div>
            <div>
                <label>Volume (liters): </label>
                <input type="number" value={volume} onChange={(e) => setVolume(e.target.value)} required />
            </div>
            <div>
                <label>Type: </label>
                <select value={type} onChange={(e) => setType(e.target.value)}>
                    <option value="Planted">Planted</option>
                    <option value="Community">Community</option>
                    <option value="Marine">Marine (Fish Only)</option>
                    <option value="Reef">Reef (Marine with Corals)</option>
                    <option value="Brackish">Brackish</option>
                    <option value="Coldwater">Coldwater</option>
                    <option value="Species-specific">Species-specific (e.g., Betta, Shrimp)</option>
                    <option value="Other">Other</option>
                </select>
            </div>
            <div>
                <label>Target Parameters (e.g., pH: 7, Temp: 25C): </label>
                <input type="text" value={targetParameters} onChange={(e) => setTargetParameters(e.target.value)} />
            </div>
            <div>
                <label>Initial Setup Notes: </label>
                <textarea value={initialSetupNotes} onChange={(e) => setInitialSetupNotes(e.target.value)} />
            </div>
            <button type="submit" style={{ marginTop: '10px' }}>Add Aquarium</button>
        </form>
    );
}

export default AquariumForm;
